/**
 * @suppress
 */
public object FfiConverterTypeLocalTransApp: FfiConverter<LocalTransApp, Pointer> {

    override fun lower(value: LocalTransApp): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): LocalTransApp {
        return LocalTransApp(value)
    }

    override fun read(buf: ByteBuffer): LocalTransApp {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: LocalTransApp) = 8UL

    override fun write(value: LocalTransApp, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



