/**
 * Full event set for Android client
 */
sealed class AppEvent {
    
    data class Hello(
        val `message`: kotlin.String) : AppEvent() {
        companion object
    }
    
    object DevicesChanged : AppEvent()
    
    
    data class ConsentRequested(
        val `fingerprint`: kotlin.String, 
        val `name`: kotlin.String) : AppEvent() {
        companion object
    }
    
    data class PairingCodeShown(
        val `fingerprint`: kotlin.String, 
        val `code`: kotlin.String) : AppEvent() {
        companion object
    }
    
    data class PairingWaitConsent(
        val `fingerprint`: kotlin.String, 
        val `name`: kotlin.String) : AppEvent() {
        companion object
    }
    
    data class PairingCodeEntry(
        val `fingerprint`: kotlin.String, 
        val `name`: kotlin.String) : AppEvent() {
        companion object
    }
    
    data class PairingResult(
        val `fingerprint`: kotlin.String, 
        val `ok`: kotlin.Boolean, 
        val `reason`: kotlin.String) : AppEvent() {
        companion object
    }
    
    data class SessionUp(
        val `fingerprint`: kotlin.String, 
        val `name`: kotlin.String) : AppEvent() {
        companion object
    }
    
    data class SessionDown(
        val `fingerprint`: kotlin.String) : AppEvent() {
        companion object
    }
    
    data class TransferUpdated(
        val `transfer`: TransferDto) : AppEvent() {
        companion object
    }
    
    data class TransferDone(
        val `jobId`: kotlin.ULong, 
        val `ok`: kotlin.Boolean, 
        val `failReason`: kotlin.String) : AppEvent() {
        companion object
    }
    
    /**
     * 接收侧文件已落盘(仅 FFI 层事件,core 无感知)。
     * paths 为绝对路径——Kotlin 据此做 MediaScanner 扫描与"查看"跳转。
     * 注意:该事件在 TransferDone 之前发出。
     */
    data class FilesSaved(
        val `jobId`: kotlin.ULong, 
        val `paths`: List<kotlin.String>) : AppEvent() {
        companion object
    }
    
    data class OfferRequested(
        val `jobId`: kotlin.ULong, 
        val `peerName`: kotlin.String, 
        val `fileCount`: kotlin.UInt, 
        val `totalSize`: kotlin.ULong, 
        val `deadlineEpochMs`: kotlin.Long) : AppEvent() {
        companion object
    }
    
    /**
     * P0-2d: 远程删除确认请求(本机是共享区持有方)
     */
    data class DeleteRequested(
        val `askId`: kotlin.ULong, 
        val `peerName`: kotlin.String, 
        val `name`: kotlin.String, 
        val `isDir`: kotlin.Boolean, 
        val `entryCount`: kotlin.ULong, 
        val `deadlineEpochMs`: kotlin.Long) : AppEvent() {
        companion object
    }
    
    data class BackupProgress(
        val `done`: kotlin.ULong, 
        val `total`: kotlin.ULong) : AppEvent() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAppEvent : FfiConverterRustBuffer<AppEvent>{
    override fun read(buf: ByteBuffer): AppEvent {
        return when(buf.getInt()) {
            1 -> AppEvent.Hello(
                FfiConverterString.read(buf),
                )
            2 -> AppEvent.DevicesChanged
            3 -> AppEvent.ConsentRequested(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> AppEvent.PairingCodeShown(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> AppEvent.PairingWaitConsent(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            6 -> AppEvent.PairingCodeEntry(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> AppEvent.PairingResult(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> AppEvent.SessionUp(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            9 -> AppEvent.SessionDown(
                FfiConverterString.read(buf),
                )
            10 -> AppEvent.TransferUpdated(
                FfiConverterTypeTransferDto.read(buf),
                )
            11 -> AppEvent.TransferDone(
                FfiConverterULong.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterString.read(buf),
                )
            12 -> AppEvent.FilesSaved(
                FfiConverterULong.read(buf),
                FfiConverterSequenceString.read(buf),
                )
            13 -> AppEvent.OfferRequested(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterLong.read(buf),
                )
            14 -> AppEvent.DeleteRequested(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterLong.read(buf),
                )
            15 -> AppEvent.BackupProgress(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AppEvent) = when(value) {
        is AppEvent.Hello -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
        is AppEvent.DevicesChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is AppEvent.ConsentRequested -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is AppEvent.PairingCodeShown -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterString.allocationSize(value.`code`)
            )
        }
        is AppEvent.PairingWaitConsent -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is AppEvent.PairingCodeEntry -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is AppEvent.PairingResult -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterBoolean.allocationSize(value.`ok`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is AppEvent.SessionUp -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is AppEvent.SessionDown -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fingerprint`)
            )
        }
        is AppEvent.TransferUpdated -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeTransferDto.allocationSize(value.`transfer`)
            )
        }
        is AppEvent.TransferDone -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`jobId`)
                + FfiConverterBoolean.allocationSize(value.`ok`)
                + FfiConverterString.allocationSize(value.`failReason`)
            )
        }
        is AppEvent.FilesSaved -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`jobId`)
                + FfiConverterSequenceString.allocationSize(value.`paths`)
            )
        }
        is AppEvent.OfferRequested -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`jobId`)
                + FfiConverterString.allocationSize(value.`peerName`)
                + FfiConverterUInt.allocationSize(value.`fileCount`)
                + FfiConverterULong.allocationSize(value.`totalSize`)
                + FfiConverterLong.allocationSize(value.`deadlineEpochMs`)
            )
        }
        is AppEvent.DeleteRequested -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`askId`)
                + FfiConverterString.allocationSize(value.`peerName`)
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterBoolean.allocationSize(value.`isDir`)
                + FfiConverterULong.allocationSize(value.`entryCount`)
                + FfiConverterLong.allocationSize(value.`deadlineEpochMs`)
            )
        }
        is AppEvent.BackupProgress -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`done`)
                + FfiConverterULong.allocationSize(value.`total`)
            )
        }
    }

    override fun write(value: AppEvent, buf: ByteBuffer) {
        when(value) {
            is AppEvent.Hello -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is AppEvent.DevicesChanged -> {
                buf.putInt(2)
                Unit
            }
            is AppEvent.ConsentRequested -> {
                buf.putInt(3)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is AppEvent.PairingCodeShown -> {
                buf.putInt(4)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterString.write(value.`code`, buf)
                Unit
            }
            is AppEvent.PairingWaitConsent -> {
                buf.putInt(5)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is AppEvent.PairingCodeEntry -> {
                buf.putInt(6)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is AppEvent.PairingResult -> {
                buf.putInt(7)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterBoolean.write(value.`ok`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is AppEvent.SessionUp -> {
                buf.putInt(8)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is AppEvent.SessionDown -> {
                buf.putInt(9)
                FfiConverterString.write(value.`fingerprint`, buf)
                Unit
            }
            is AppEvent.TransferUpdated -> {
                buf.putInt(10)
                FfiConverterTypeTransferDto.write(value.`transfer`, buf)
                Unit
            }
            is AppEvent.TransferDone -> {
                buf.putInt(11)
                FfiConverterULong.write(value.`jobId`, buf)
                FfiConverterBoolean.write(value.`ok`, buf)
                FfiConverterString.write(value.`failReason`, buf)
                Unit
            }
            is AppEvent.FilesSaved -> {
                buf.putInt(12)
                FfiConverterULong.write(value.`jobId`, buf)
                FfiConverterSequenceString.write(value.`paths`, buf)
                Unit
            }
            is AppEvent.OfferRequested -> {
                buf.putInt(13)
                FfiConverterULong.write(value.`jobId`, buf)
                FfiConverterString.write(value.`peerName`, buf)
                FfiConverterUInt.write(value.`fileCount`, buf)
                FfiConverterULong.write(value.`totalSize`, buf)
                FfiConverterLong.write(value.`deadlineEpochMs`, buf)
                Unit
            }
            is AppEvent.DeleteRequested -> {
                buf.putInt(14)
                FfiConverterULong.write(value.`askId`, buf)
                FfiConverterString.write(value.`peerName`, buf)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterBoolean.write(value.`isDir`, buf)
                FfiConverterULong.write(value.`entryCount`, buf)
                FfiConverterLong.write(value.`deadlineEpochMs`, buf)
                Unit
            }
            is AppEvent.BackupProgress -> {
                buf.putInt(15)
                FfiConverterULong.write(value.`done`, buf)
                FfiConverterULong.write(value.`total`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







sealed class AppException: kotlin.Exception() {
    
    class Io(
        
        // 手工补丁:errorMessage 字段 + override message(重生成后需重做)
        message: kotlin.String
        ) : AppException() {
        val errorMessage: kotlin.String = message
        override val message: kotlin.String get() = errorMessage
    }
    
    class Internal(
        
        // 手工补丁:errorMessage 字段 + override message(重生成后需重做)
        message: kotlin.String
        ) : AppException() {
        val errorMessage: kotlin.String = message
        override val message: kotlin.String get() = errorMessage
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AppException> {
        override fun lift(error_buf: RustBuffer.ByValue): AppException = FfiConverterTypeAppException.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAppException : FfiConverterRustBuffer<AppException> {
    override fun read(buf: ByteBuffer): AppException {
        

        return when(buf.getInt()) {
            1 -> AppException.Io(
                FfiConverterString.read(buf),
                )
            2 -> AppException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AppException): ULong {
        return when(value) {
            is AppException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is AppException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: AppException, buf: ByteBuffer) {
        when(value) {
            is AppException.Io -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is AppException.Internal -> {
                buf.putInt(2)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



